path = os.path.expanduser("~/session_58206744/session.json")
with open(path) as f:
    sess = json.load(f)
msgs = sess["messages"]

def dump_range(start, end, max_content=3000, max_thinking=1200, max_tool=400):
    for i in range(start, min(end, len(msgs))):
        m = msgs[i]
        role = m.get("role")
        ts = m.get("timestamp","")
        tools = m.get("tool_uses") or []
        content = m.get("content") or ""
        thinking = m.get("thinking") or ""
        print(f"\n{'='*70}")
        print(f"MSG {i} role={role} ts={ts} clen={len(content)} tlen={len(thinking)} ntools={len(tools)}")
        if tools:
            for t in tools:
                inp = t.get("input")
                tool = t.get("tool")
                if isinstance(inp, dict):
                    preview_parts = []
                    for k,v in inp.items():
                        s = str(v)
                        if len(s) > max_tool:
                            s = s[:max_tool] + f"...[{len(str(v))-max_tool} more]"
                        preview_parts.append(f"    {k}: {s}")
                    print(f"  TOOL {tool}:")
                    print("\n".join(preview_parts))
                else:
                    print(f"  TOOL {tool}: {str(inp)[:max_tool]}")
        if thinking:
            print(f"  THINKING:\n{thinking[:max_thinking]}")
            if len(thinking) > max_thinking:
                print(f"  ...[{len(thinking)-max_thinking} more thinking]")
        if content:
            print(f"  CONTENT:\n{content[:max_content]}")
            if len(content) > max_content:
                print(f"  ...[{len(content)-max_content} more]")

